    // ── VAL-BRIDGE-004: every MethodDecl exposed as a callable method ──

    #[tokio::test]
    async fn bridge_exposes_all_declared_methods() {
        let base = test_base_dir();
        let monolith_path = write_test_monolith(&base);
        let per_plugin_dir = base.join("opdbus/schemas");
        let routes = SchemaRouter::load_routes_from(&monolith_path, &per_plugin_dir);

        // beta declares SetKey and GetKey — both must be exposed.
        let beta = routes["beta"].clone();
        let iface = SchemaBackedInterface::new("beta".to_string(), beta);

        let declared = iface.declared_methods();
        assert!(declared.contains(&"SetKey".to_string()));
        assert!(declared.contains(&"GetKey".to_string()));
        assert_eq!(declared.len(), 2, "every declared MethodDecl is exposed");

        assert!(iface.exposes_method("SetKey"));
        assert!(iface.exposes_method("GetKey"));
        assert!(!iface.exposes_method("Nonexistent"));

        // A declared method is callable (passes the method-existence gate);
        // an undeclared method is rejected as UnknownMethod.
        let unknown = iface
            .call("Nonexistent".to_string(), "{}".to_string())
            .await;
        assert!(
            matches!(unknown, Err(zbus::fdo::Error::UnknownMethod(_))),
            "undeclared method must be rejected as UnknownMethod"
        );
        let known = iface.call("GetKey".to_string(), "{}".to_string()).await;
        assert!(
            !matches!(known, Err(zbus::fdo::Error::UnknownMethod(_))),
            "a declared method must be exposed (not rejected as UnknownMethod)"
        );

        cleanup(&base);
    }

    // ── VAL-BRIDGE-005: every SignalDecl exposed as an emittable signal ──

    #[test]
    fn bridge_exposes_all_declared_signals() {
        let base = test_base_dir();
        let monolith_path = write_test_monolith(&base);
        let per_plugin_dir = base.join("opdbus/schemas");
        let routes = SchemaRouter::load_routes_from(&monolith_path, &per_plugin_dir);

        // beta declares KeyRotated and KeyExpired signals.
        let beta = routes["beta"].clone();
        let iface = SchemaBackedInterface::new("beta".to_string(), beta);

        let signals = iface.declared_signals();
        assert!(signals.contains(&"KeyRotated".to_string()));
        assert!(signals.contains(&"KeyExpired".to_string()));
        assert_eq!(signals.len(), 2, "every declared SignalDecl is exposed");

        assert!(iface.exposes_signal("KeyRotated"));
        assert!(iface.exposes_signal("KeyExpired"));
        assert!(!iface.exposes_signal("Nonexistent"));

        // alpha declares exactly one signal: StatusChanged.
        let alpha = routes["alpha"].clone();
        let alpha_iface = SchemaBackedInterface::new("alpha".to_string(), alpha);
        assert_eq!(
            alpha_iface.declared_signals(),
            vec!["StatusChanged".to_string()]
        );

        cleanup(&base);
    }

    // ── Route extraction preserves the full method + signal surface ──

    #[test]
    fn route_extracts_methods_and_signals_from_schema() {
        let base = test_base_dir();
        let monolith_path = write_test_monolith(&base);
        let per_plugin_dir = base.join("opdbus/schemas");
        let routes = SchemaRouter::load_routes_from(&monolith_path, &per_plugin_dir);

        let beta = &routes["beta"];
        // Methods preserved with full MethodDecl bodies.
        assert_eq!(beta.methods.len(), 2);
        assert_eq!(beta.methods["SetKey"]["side_effect"], json!("mutation"));
        assert_eq!(
            beta.methods["SetKey"]["required_capability"],
            json!("beta.set_key")
        );
        // Signals preserved with full SignalDecl bodies.
        assert_eq!(beta.signals.len(), 2);
        let names: Vec<&str> = beta
            .signals
            .iter()
            .filter_map(|s| s["name"].as_str())
            .collect();
        assert!(names.contains(&"KeyRotated"));
        assert!(names.contains(&"KeyExpired"));

        cleanup(&base);
    }
}

//! The Shuttle — gRPC Bridge Binary
//!
//! Zero-trust gRPC gateway enforcing the Absolute Base rule via
//! GhostbridgeInterceptor. Reads the IdentitySled from shared memory
//! (/dev/shm/plugin_schema.dat) and rejects any request whose footprint
//! does not match the current Strike/Etch.
//!
//! Dual listener:
//!   - TCP on GRPC_BIND (default 127.0.0.1:18789) — Xray redirect target.
//!   - UDS on GHOSTBRIDGE_SOCKET_PATH (default /run/ghostbridge/container.sock)
//!     — container access with full tonic stack and identity injection.
//!
//! SchemaRouter is wired into the live DbusPassthrough path: every plugin in
//! the SHM catalog is automatically routable without hand-rolled services.

use std::net::SocketAddr;
use std::sync::Arc;

use op_grpc_bridge::{
    grpc_server::{run_grpc_server, OperationGrpcServer},
    schema_engine::SchemaEngine,
    schema_router::SchemaRouter,
    shared_socket,
};
use op_jsonrpc::nonnet::NonNetDb;
use op_network::rovs_proxy::OvsdbDbusClient;
use op_state_store::{ChainConfig, EventChain};
use tokio::sync::RwLock;

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::from_default_env()
                .add_directive("op_grpc_bridge=info".parse()?)
                .add_directive("info".parse()?),
        )
        .init();

    // ── Build SchemaEngine (authoritative mutation pipeline) ─────────────────
    let event_chain = Arc::new(RwLock::new(EventChain::new(ChainConfig::default())));
    let ovsdb = Arc::new(OvsdbDbusClient::new());
    let nonnet = Arc::new(NonNetDb::new());
    let schema_engine = Arc::new(SchemaEngine::new(event_chain, ovsdb, nonnet));

    // ── Schema Router (dynamic D-Bus routing from live schema catalog) ───────
    let schema_router = Arc::new(SchemaRouter::new(schema_engine.dbus_connection.clone()));

    // Authoritative D-Bus object registration:
    // The bridge brings the schema-defined objects into existence on the bus.
    let sr_init = schema_router.clone();
    let se_init = schema_engine.clone();
    tokio::spawn(async move {
        // Wait for D-Bus connection to be ready
        if let Ok(conn) = se_init.dbus_connection().await {
            if let Err(e) = sr_init.register_objects().await {
                tracing::error!(error = %e, "Failed to register authoritative D-Bus objects");
            } else {
                // Request the canonical bus name for the bridge. The bridge is
                // the sole owner of org.opdbus.v1 (see canonical::BASE_SERVICE_NAME).
                if let Err(e) = conn.request_name("org.opdbus.v1").await {
                    tracing::warn!(error = %e, "Failed to request D-Bus name (likely already owned)");
                }
            }
        }
    });

    let plugin_count = schema_router.list_plugin_ids().await.len();
    tracing::info!(
        plugin_count,
        "SchemaRouter initialized — all plugins auto-exposed to gRPC"
    );

    // ── Shared UDS (container access — full tonic stack) ────────────────────
    let se_uds = schema_engine.clone();
    let sr_uds = schema_router.clone();
    tokio::spawn(async move {
        match shared_socket::bind_shared_socket().await {
            Ok(incoming) => {
                tracing::info!("Shared container socket active — serving full gRPC stack over UDS");

                use op_grpc_bridge::proto::dbus_passthrough_server::DbusPassthroughServer;
                use op_grpc_bridge::proto::plugin_service_server::PluginServiceServer;
                use op_grpc_bridge::proto::state_sync_server::StateSyncServer;

                let server = OperationGrpcServer::new(se_uds).with_schema_router(sr_uds);

                let result = tonic::transport::Server::builder()
                    .add_service(DbusPassthroughServer::with_interceptor(
                        server.clone(),
                        shared_socket::uds_identity_interceptor,
                    ))
                    .add_service(PluginServiceServer::with_interceptor(
                        server.clone(),
                        shared_socket::uds_identity_interceptor,
                    ))
                    .add_service(StateSyncServer::with_interceptor(
                        server.clone(),
                        shared_socket::uds_identity_interceptor,
                    ))
                    .serve_with_incoming(incoming)
                    .await;

                if let Err(e) = result {
                    tracing::error!(error = %e, "UDS gRPC server exited with error");
                }
            }
            Err(e) => {
                tracing::warn!(
                    error = %e,
                    "Failed to bind shared container socket — container access unavailable"
                );
            }
        }
    });

    // ── TCP Bind address ────────────────────────────────────────────────────
    let addr: SocketAddr = std::env::var("GRPC_BIND")
        .unwrap_or_else(|_| "127.0.0.1:18789".to_string())
        .parse()
