    async fn call(
        &self,
        request: Request<crate::proto::DbusCallRequest>,
    ) -> Result<Response<crate::proto::DbusCallResponse>, Status> {
        let req = request.into_inner();
        let conn = self
            .schema_engine
            .dbus_connection()
            .await
            .map_err(|e| Status::unavailable(format!("D-Bus not available: {e}")))?;

        let bus_conn = match req.bus.as_str() {
            "session" => {
                let session = Connection::session()
                    .await
                    .map_err(|e| Status::unavailable(format!("session bus unavailable: {e}")))?;
                session
            }
            _ => conn,
        };

        // ── Schema-driven routing ────────────────────────────────────────────
        // If destination is empty, resolve from the schema catalog using the
        // path. This allows callers to specify only the plugin path and method
        // without knowing the D-Bus destination/interface.
        use crate::schema_passthrough::resolve_from_schema_or_explicit;
        let resolved = resolve_from_schema_or_explicit(&req.destination, &req.path, &req.interface);

        let (destination, path, interface) = match resolved {
            crate::schema_passthrough::ResolvedRoute::Explicit {
                destination,
                path,
                interface,
            } => (destination, path, interface),
            crate::schema_passthrough::ResolvedRoute::SchemaResolved {
                plugin_id,
                sub_path: _,
            } => {
                let dest = op_plugins::canonical::BASE_SERVICE_NAME.to_string();
                let path = op_plugins::canonical::plugin_path(&plugin_id);
                let iface = op_plugins::canonical::plugin_interface(&plugin_id);
                (dest, path, iface)
            }
        };

        let proxy = Proxy::new(
            &bus_conn,
            destination.as_str(),
            path.as_str(),
            interface.as_str(),
        )
        .await
        .map_err(|e| Status::internal(format!("proxy build failed: {e}")))?;

        let result: String = proxy
            .call(req.method.clone(), &(req.json_body.clone(),))
            .await
            .map_err(|e| Status::internal(format!("D-Bus call '{}' failed: {e}", req.method)))?;

        Ok(Response::new(crate::proto::DbusCallResponse {
            success: true,
            json_result: result,
            error: String::new(),
        }))
    }

